code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x, grid[y][x]))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] != 0:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            objects.append(cells)

    shifts = [0] * len(objects)
    order = sorted(range(len(objects)), key=lambda i: max(c for _,c,_ in objects[i]), reverse=True)
    moved = True
    while moved:
        moved = False
        for i in order:
            cells = objects[i]
            while True:
                next_shift = shifts[i] + 1
                own = {(r, c + next_shift) for r,c,_ in cells}
                if any(c + next_shift >= w for _,c,_ in cells):
                    break
                blocked = False
                for j, other in enumerate(objects):
                    if i == j:
                        continue
                    other_cells = {(r, c + shifts[j]) for r,c,_ in other}
                    if own & other_cells:
                        blocked = True
                        break
                if blocked:
                    break
                shifts[i] = next_shift
                moved = True
    out = [[0] * w for _ in range(h)]
    for i, cells in enumerate(objects):
        for r,c,color in cells:
            out[r][c + shifts[i]] = color
    return out
'''
